css:
.frame {
  position: relative;
  width: 260px;
  height: 180px;
  margin: 16px 24px 24px 16px;
}

.backdrop {
  position: absolute;
  inset: 16px -16px -16px 16px; /* hangs out past the photo */
  border-radius: 8px;
  background: #fed7aa;
}

.photo {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  height: 100%;
  border-radius: 8px;
  background: #3f3f46;
  color: #fafafa;
}
